      --wa-blue: #5bc5ff;
      --wa-blue-soft: #9bdcff;
      --wa-soul: #76f0d2;
      --wa-text: #e8f2f7;
      --wa-muted: #9cafbb;
      --wa-alert: #ff7185;
      box-sizing: border-box;
      width: 100%;
      margin: .8rem 0;
      color: var(--wa-text);
      font: 14px/1.55 ui-sans-serif, system-ui, "Microsoft YaHei", sans-serif;
    }
    .wa-panel * { box-sizing: border-box; }
    .wa-shell {
      overflow: hidden;
      border: 1px solid var(--wa-line);
      border-radius: 16px;
      background:
        radial-gradient(circle at 88% -10%, rgba(91, 197, 255, .14), transparent 34%),
        radial-gradient(circle at 8% 12%, rgba(118, 240, 210, .07), transparent 28%),
        linear-gradient(155deg, var(--wa-ink), var(--wa-night));
      box-shadow: 0 12px 34px rgba(0, 0, 0, .34), inset 0 0 36px rgba(91, 197, 255, .025);
    }
    .wa-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: .8rem;
      padding: .8rem 1rem;
      border-bottom: 1px solid rgba(91, 197, 255, .2);
    }
    .wa-brand { display: flex; align-items: center; gap: .65rem; min-width: 0; }
    .wa-lamp {
      width: .72rem;
      height: .95rem;
      border-radius: 52% 48% 56% 44%;
      background: var(--wa-soul);
      box-shadow: 0 0 9px rgba(118, 240, 210, .8), 0 0 22px rgba(91, 197, 255, .38);
      animation: wa-breathe 3.4s ease-in-out infinite;
      flex: 0 0 auto;
    }
    .wa-title { margin: 0; font-size: 1rem; letter-spacing: .08em; overflow-wrap: anywhere; }
    .wa-version { color: var(--wa-blue-soft); font-size: .75rem; white-space: nowrap; }
    .wa-tabs { display: flex; gap: .4rem; padding: .65rem .7rem 0; overflow-x: auto; }
    .wa-tab {
      appearance: none;
      border: 1px solid var(--wa-line);
      border-radius: 999px;
      padding: .4rem .72rem;
      color: var(--wa-muted);
      background: rgba(255, 255, 255, .025);
      cursor: pointer;
      font: inherit;
      white-space: nowrap;
    }
    .wa-tab:hover, .wa-tab:focus-visible { border-color: var(--wa-blue); outline: none; }
    .wa-tab[aria-selected="true"] {
      color: var(--wa-text);
      border-color: var(--wa-blue);
      background: rgba(91, 197, 255, .14);
      box-shadow: 0 0 14px rgba(91, 197, 255, .12);
    }
    .wa-page { padding: .75rem; }
    .wa-page[hidden] { display: none; }
    .wa-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .62rem; }
    .wa-card {
      min-width: 0;
      padding: .72rem;
      border: 1px solid rgba(41, 68, 95, .86);
      border-radius: 11px;
      background: var(--wa-card);
    }
    .wa-card--wide { grid-column: 1 / -1; }
    .wa-card--urgent {
      border-color: rgba(255, 113, 133, .7);
      animation: wa-alert 1.9s ease-in-out infinite;
    }
    .wa-label { margin: 0 0 .35rem; color: var(--wa-blue-soft); font-size: .72rem; letter-spacing: .08em; }
    .wa-value { margin: 0; overflow-wrap: anywhere; }
    .wa-value + .wa-value { margin-top: .22rem; }
    .wa-muted { color: var(--wa-muted); }
    .wa-chip {
      display: inline-flex;
      align-items: center;
      gap: .3rem;
      margin: .15rem .2rem .15rem 0;
      padding: .14rem .45rem;
      border: 1px solid rgba(91, 197, 255, .28);
      border-radius: 999px;
      color: var(--wa-blue-soft);
      background: rgba(91, 197, 255, .06);
      font-size: .78rem;
    }
    .wa-person {
      border: 1px solid rgba(41, 68, 95, .72);
      border-radius: 10px;
      background: rgba(7, 11, 18, .34);
    }
    .wa-person + .wa-person { margin-top: .52rem; }
    .wa-person summary {
      display: flex;
      justify-content: space-between;
      gap: .6rem;
      padding: .62rem .68rem;
      cursor: pointer;
      list-style: none;
    }
    .wa-person summary::-webkit-details-marker { display: none; }
    .wa-person summary:focus-visible { outline: 1px solid var(--wa-blue); outline-offset: -2px; }
    .wa-name { font-weight: 700; color: var(--wa-text); }
    .wa-status { color: var(--wa-soul); text-align: right; }
    .wa-person-body { padding: 0 .68rem .7rem; border-top: 1px dashed rgba(91, 197, 255, .16); }
    .wa-person-meta { margin: .55rem 0; color: var(--wa-muted); }
    .wa-meter-row {
      display: grid;
      grid-template-columns: 3.3rem minmax(0, 1fr) 4.6rem;
      align-items: center;
      gap: .45rem;
      margin: .34rem 0;
    }
    .wa-meter {
      position: relative;
      height: .42rem;
      overflow: hidden;
      border-radius: 999px;
      background: rgba(255, 255, 255, .07);
    }
    .wa-meter > span {
      position: absolute;
      left: 50%;
      top: 0;
      bottom: 0;
      width: 0;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--wa-soul), var(--wa-blue));
      transition: width .3s ease, left .3s ease;
    }
    .wa-meter > span[data-negative="true"] { background: linear-gradient(90deg, var(--wa-alert), #d485ff); }
    .wa-meter-text { color: var(--wa-muted); font-size: .75rem; text-align: right; }
    .wa-edge {
      padding: .55rem 0;
      border-top: 1px dashed rgba(91, 197, 255, .15);
    }
    .wa-edge:first-child { border-top: 0; padding-top: 0; }
    .wa-event-id { color: var(--wa-soul); font-weight: 700; letter-spacing: .08em; }
    .wa-list { margin: .3rem 0 0; padding-left: 1.15rem; }
    .wa-list li + li { margin-top: .25rem; }
    .wa-foot { padding: .55rem .9rem .75rem; color: var(--wa-muted); font-size: .75rem; }
    .wa-btn {
      margin-top: .55rem;
      padding: .42rem .8rem;
      border: 1px solid rgba(91, 197, 255, .45);
      border-radius: 999px;
      color: var(--wa-blue-soft);
      background: rgba(91, 197, 255, .08);
      font: inherit;
      font-size: .8rem;
      cursor: pointer;
    }
    .wa-btn:hover:not(:disabled), .wa-btn:focus-visible:not(:disabled) {
      border-color: var(--wa-blue);
      color: var(--wa-text);
      background: rgba(91, 197, 255, .16);
    }
    .wa-btn:disabled { opacity: .45; cursor: not-allowed; }
    .wa-error {
      margin: .75rem;
      padding: .7rem;
      border: 1px dashed var(--wa-alert);
      border-radius: 9px;
      color: #ffc3cc;
    }
    @keyframes wa-breathe {
      0%, 100% { opacity: .64; transform: scale(.92); }
      50% { opacity: 1; transform: scale(1.08); }
    }
    @keyframes wa-alert {
      0%, 100% { box-shadow: 0 0 0 rgba(255, 113, 133, 0); }
      50% { box-shadow: 0 0 16px rgba(255, 113, 133, .14); }
    }
    @media (max-width: 600px) {
      .wa-grid { grid-template-columns: 1fr; }
      .wa-card--wide { grid-column: auto; }
      .wa-meter-row { grid-template-columns: 3rem minmax(0, 1fr) 4rem; }
